    reg        clk;
    reg        reset;
    wire [3:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // 3. Stimulus & self-checking
    integer errors = 0;
    reg [3:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
