        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        // Release reset
        @(negedge clk);
        reset = 0;

        // Run through a full cycle and beyond (e.g., 20 cycles to test rollover)
        repeat (20) begin
            @(posedge clk);
            #1; // Wait slightly past clock edge for output update

            // Calculate expected value based on previous expected value
            expected_q = expected_q + 4'd1;

            if (q !== expected_q) begin
                $display("Mismatch at time %0t: q = %b (expected %b)", $time, q, expected_q);
                errors = errors + 1;
            end

            // Test synchronous reset midway
            if ($time == 50) begin
                reset = 1;
                expected_q = 4'd0;
            end else if ($time == 60) begin
                reset = 0;
            end
        end

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
